#include <iostream>
#include <string>

using namespace std;

/**
 * 題目 10416: Last Digit
 * 題目要求計算 S = 1^1 + 2^2 + 3^3 + ... + N^N 的最後一位數字。
 * N 的範圍非常大 (可達 2*10^100)，因此需要以字串讀入。
 * 
 * 分析：
 * 1. 我們只需要最後一位數字，即 S % 10。
 * 2. (n^n) % 10 的週期：
 *    - 底數 n % 10 的週期是 10。
 *    - 指數 n 在冪運算中對於模 10 的週期取決於 phi(10) = 4。
 *    - 因此 (n^n) % 10 的週期是 lcm(10, 4) = 20。
 * 3. 累加和 S(N) % 10 的週期：
 *    - 由於序列的每一項 (n^n) % 10 週期為 20，
 *    - 但由於底數也在變，整個 S(N) % 10 的週期實際上是 100。
 *    - 即 S(N) % 10 = S(N % 100) % 10。
 */

int main() {
    string n_str;
    while (cin >> n_str && n_str != "0") {
        int len = n_str.length();
        int n_mod_100 = 0;
        if (len == 1) {
            n_mod_100 = n_str[0] - '0';
        } else {
            n_mod_100 = (n_str[len - 2] - '0') * 10 + (n_str[len - 1] - '0');
        }

        int last_digit_sum = 0;
        for (int i = 1; i <= n_mod_100; ++i) {
            int base = i % 10;
            int exp = i;
            // 由於我們只需要最後一位，直接循環乘法即可
            int term = 1;
            for (int k = 0; k < exp; ++k) {
                term = (term * base) % 10;
            }
            last_digit_sum = (last_digit_sum + term) % 10;
        }
        cout << last_digit_sum << endl;
    }
    return 0;
}
